import {activityOutcomeMarkup,mountActivityOutcome} from '../activity-outcome.js';
import {STAGES,ROBOT_COMMANDS,SENSORS,LIMITS,stageById,parseBoard,initialRobot,reduceRobot,countNodes,editProgram,initialRobotSave,validateRobotSave,readSensor} from './robot-lab.js';
import {createWorkshopViewport} from './robot-board.js';
import {createComputerSession} from './robot-session.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pathKey=p=>p.join('.'),parsePath=value=>value?value.split('.').map(Number):[];
const BODY=`<div id="robot-panel" class="robot-panel"><nav id="robot-stages" class="robot-stages" aria-label="공방 고르기"></nav><div class="robot-heading"><div><span id="robot-concept"></span><h3 id="robot-stage-title"></h3></div><p id="robot-objective"></p></div><div class="robot-layout"><section class="robot-world"><div class="robot-viewport"><canvas id="robot-world-canvas" aria-label="명령에 따라 움직이는 입체 로봇 작업장"></canvas><canvas id="robot-map-fallback" width="600" height="600" aria-label="로봇 작업장 위쪽 지도" hidden></canvas></div><div class="robot-view-controls"><button data-robot-action="rotate" aria-label="작업장 시점 돌리기">시점 ↶</button><button data-robot-action="top" aria-pressed="false" id="robot-top">위에서 보기</button><button data-robot-action="computer" aria-pressed="false" id="robot-computer">도름이 보기</button></div><p id="robot-render-note" hidden>입체 화면을 열지 못해 위쪽 지도로 보여요. 모든 명령은 그대로 작동해요.</p><div id="robot-goals" class="robot-goals"></div><p class="robot-legend">금빛 별 = 도착 · 고리 = 부품 · 둥근 버튼 = 스위치 · 막대 = 문</p><div class="robot-run"><button data-robot-action="run" id="robot-run" class="primary">▶ 실행</button><button data-robot-action="step" id="robot-step">한 단계</button><button data-robot-action="pause" id="robot-pause">멈춤</button><button data-robot-action="rewind" id="robot-rewind">처음 위치</button><label>속도 <select id="robot-speed" data-robot-change="speed"><option value=".48">보통</option><option value=".85">천천히</option></select></label></div><p id="robot-status" class="robot-status" role="status" aria-live="polite"></p><p id="robot-position" class="robot-position"></p><details class="robot-help"><summary>센서와 실행 기록</summary><div id="robot-sensors"></div><ol id="robot-trace"></ol></details></section><section class="robot-editor" aria-label="명령 블록 편집"><div class="robot-editor-heading"><h3>나의 명령</h3><span id="robot-count"></span></div><p id="robot-efficiency" class="robot-efficiency"></p><p class="robot-instruction">넣을 곳을 고르고 아래 명령을 눌러요</p><div id="robot-palette" class="robot-palette"></div><div class="robot-edit-actions"><button data-robot-action="undo" id="robot-undo">되돌리기</button><button data-robot-action="clear" id="robot-clear">전체 비우기</button></div><div id="robot-program" class="robot-program"></div><p id="robot-save-status" class="robot-save-status"></p><button id="robot-save-retry" data-robot-action="save" hidden>저장 다시 시도</button><details class="robot-help"><summary>생각해 볼 힌트</summary><p id="robot-hint"></p><div id="robot-more-hints"></div><p id="robot-lesson"></p><p id="robot-challenge"></p></details>${activityOutcomeMarkup("robot-complete")}</section></div></div>`;
export function createRobotController({ui,getView,getProgress=()=>({}),transact=()=>false,discover=()=>{},getActors=()=>null,doc=globalThis.document,win=globalThis.window,reduced=false,createViewport=createWorkshopViewport,createSession=createComputerSession}){
 let live=null;
 const $=id=>doc.querySelector('#'+id);
 function close(){const s=live;if(!s)return;live=null;s.alive=false;s.outcome?.dispose();s.state=reduceRobot(s.state,{type:'CANCEL'});s.visual?.updateLab?.(s.state);s.viewport?.dispose();s.session?.dispose();for(const[node,type,fn]of s.listeners)node?.removeEventListener(type,fn);}
 function save(s){const state=s.state;let completed=[...s.saved.completed],best={...s.saved.best};if(state.phase==='complete'){completed=[...new Set([...completed,state.stageId])];best[state.stageId]=Math.min(best[state.stageId]??LIMITS.nodes,countNodes(state.program));}s.saved={...s.saved,selected:state.stageId,programs:{...s.saved.programs,[state.stageId]:state.program},completed,best};const ok=transact({type:'SAVE_ROBOT',lab:s.saved});$('robot-save-status').textContent=ok?'명령과 완료 기록을 이 브라우저에 저장했어요':'저장하지 못했어요. 이번 명령은 창을 닫기 전까지 임시로 유지돼요';$('robot-save-retry').hidden=ok;return ok;}
 function programHTML(s,body,path=[]){const running=s.state.phase==='running',key=pathKey(path),selected=key===pathKey(s.target);return `<div class="robot-sequence${selected?' insertion-target':''}" data-depth="${path.length}">${body.map((n,i)=>{const p=[...path,i],k=pathKey(p),active=k===pathKey(s.state.activePath)&&s.state.steps>0,controls=running?' disabled':'';let options='';if(n.type==='repeat')options=`<label>횟수 <select data-robot-change="count" data-path="${k}" aria-label="${k} 반복 횟수"${controls}>${[2,3,4,5,6,7,8].map(v=>`<option value="${v}"${n.count===v?' selected':''}>${v}번</option>`).join('')}</select></label>`;if(n.type==='if')options=`<select data-robot-change="sensor" data-path="${k}" aria-label="${k} 센서"${controls}>${stageById(s.state.stageId).sensors.map(id=>`<option value="${id}"${n.sensor===id?' selected':''}>${SENSORS[id]}</option>`).join('')}</select>`;return `<div class="robot-node${active?' executing':''}${active&&s.state.phase==='error'?' robot-error':''}" data-node-path="${k}"><div class="robot-node-row"><span class="robot-node-label">${i+1}. ${escape(ROBOT_COMMANDS[n.type])}</span><div class="robot-node-moves"><button data-robot-action="up" data-path="${k}" aria-label="${k} 명령 위로"${controls}${i===0?' disabled':''}>↑</button><button data-robot-action="down" data-path="${k}" aria-label="${k} 명령 아래로"${controls}${i===body.length-1?' disabled':''}>↓</button><button data-robot-action="remove" data-path="${k}" aria-label="${k} 명령 지우기"${controls}>×</button></div></div>${options}${n.body?programHTML(s,n.body,p):''}</div>`;}).join('')}<button class="robot-insert" data-robot-action="target" data-path="${key}" aria-pressed="${selected}"${running?' disabled':''}>${selected?'＋ 여기에 넣는 중':path.length?'＋ 이 묶음 안에 넣기':'＋ 맨 끝에 넣기'}</button>${!body.length&&!path.length?'<p class="robot-empty">로봇에게 첫 명령을 알려 주세요</p>':''}</div>`;}
 function render(s,{editor=false}={}){if(live!==s||!s.alive)return;const st=s.state,stage=stageById(st.stageId),b=parseBoard(stage),running=st.phase==='running';s.visual?.updateLab?.(st,{snap:reduced});s.viewport.update(st);s.session?.update(st.steps,running);$('robot-status').textContent=(st.phase==='error'?`${st.activePath.map(i=>i+1).join(' → ')}번 명령에서 멈춤 · `:'')+st.message;$('robot-status').dataset.phase=st.phase;$('robot-position').textContent=`위쪽 지도의 (${st.x+1}, ${st.z+1}) · ${['북','동','남','서'][st.heading]}쪽 · 실행 ${st.steps}단계`;$('robot-goals').textContent=`부품 ${st.parts.length} / ${b.parts.length}${b.switches.length?' · 문 '+(st.gateOpen?'열림':'닫힘'):''}${b.parcel?' · 상자 '+(st.delivered?'배달 완료':st.carrying?'운반 중':'찾기'):''}`;$('robot-run').textContent=st.phase==='paused'?'▶ 이어서':'▶ 실행';$('robot-run').disabled=running||!st.program.length;$('robot-step').disabled=running||!st.program.length;$('robot-pause').disabled=!running;$('robot-rewind').disabled=!st.steps&&!running;$('robot-clear').disabled=running||!st.program.length;$('robot-undo').disabled=running||!s.history.length;$('robot-count').textContent=`${countNodes(st.program)} / ${LIMITS.nodes}블록`;
  if(editor||s.lastPhase!==st.phase||s.lastStep!==st.steps){$('robot-program').innerHTML=programHTML(s,st.program);$('robot-palette').innerHTML=stage.palette.map(type=>`<button data-robot-action="append" data-command="${type}"${running||countNodes(st.program)>=LIMITS.nodes?' disabled':''}>${escape(ROBOT_COMMANDS[type])}</button>`).join('');}s.lastPhase=st.phase;s.lastStep=st.steps;$('robot-sensors').textContent=stage.sensors.map(sensor=>`${SENSORS[sensor]}: ${readSensor(st,sensor)?'예':'아니요'}`).join(' · ')||'이 공방은 순서와 방향을 먼저 익혀요';$('robot-trace').innerHTML=st.trace.slice(-5).map(t=>`<li>${t.step}. ${t.path.map(i=>i+1).join(' → ')}번 ${escape(ROBOT_COMMANDS[t.type])}${t.sensorResult===undefined?'':t.sensorResult?' · 안쪽 실행':' · 건너뜀'}</li>`).join('');s.outcome?.update({show:st.phase==='complete',title:'공방 임무 완료!',detail:`${countNodes(st.program)}블록으로 해냈어요. ${countNodes(st.program)<=stage.target?'짧게 표현하기 도전도 성공!':'명령을 더 짧게 바꾸는 도전도 해 보세요.'}`,saveText:$('robot-save-status').textContent,next:stage===STAGES.at(-1)?null:{label:'다음 공방',run:()=>chooseStage(s,STAGES[STAGES.indexOf(stage)+1].id)}});
 }
 function stageHeader(s){const st=stageById(s.state.stageId);$('robot-stages').innerHTML=STAGES.map((stage,i)=>`<button data-robot-action="stage" data-id="${stage.id}" data-advanced="${!!stage.advanced}" aria-current="${st.id===stage.id?'step':'false'}" aria-label="${i+1} ${stage.advanced?'심화 ':''}${stage.title}${s.saved.completed.includes(stage.id)?' 완료':''}">${i+1}${stage.advanced?' 심화':''}${s.saved.completed.includes(stage.id)?' ✓':''}</button>`).join('');$('robot-concept').textContent=`공방 ${STAGES.indexOf(st)+1} / ${STAGES.length} · ${st.advanced?'심화 · ':''}${st.concept}`;$('robot-stage-title').textContent=st.title;$('robot-objective').textContent=st.goal;$('robot-hint').textContent=st.hint;$('robot-more-hints').innerHTML=(st.hints??[]).reduceRight((inside,hint,i)=>`<details class="robot-hint-step"><summary>힌트 ${i+2} 보기</summary><p>${escape(hint)}</p>${inside}</details>`,'');$('robot-efficiency').textContent=`선택 도전: ${st.target}블록 이하${s.saved.best[st.id]?' · 내 최고 '+s.saved.best[st.id]+'블록':''}`;$('robot-lesson').textContent=st.lesson;$('robot-challenge').textContent=`선택 도전: ${st.target}블록 이하로 표현하기. 더 길어도 목표를 이루면 성공이에요.`;}
 function apply(s,a){if(live!==s||!s.alive)return;const old=s.state;s.state=reduceRobot(old,a);if(s.state===old)return;if(s.state.steps===old.steps&&s.state.phase===old.phase&&a.type==='TICK')return;if(s.state.phase==='complete'&&old.phase!=='complete'){save(s);discover('home-code');stageHeader(s);}render(s);}
 function edit(s,p){if(!p){$('robot-status').textContent='묶음은 세 겹, 명령은 48개까지예요. 다른 넣을 곳을 골라 주세요';return;}s.history.push(s.state.program);if(s.history.length>20)s.history.shift();s.state=reduceRobot(s.state,{type:'EDIT',program:p});save(s);render(s,{editor:true});}
 function chooseStage(s,id){if(!STAGES.some(stage=>stage.id===id))return;apply(s,{type:'PAUSE'});s.state=initialRobot(id,s.saved.programs[id]??[],s.state.generation+1);s.target=[];s.history=[];save(s);stageHeader(s);render(s,{editor:true});}
 function bind(s,node,type,fn){node?.addEventListener(type,fn);s.listeners.push([node,type,fn]);}
 function open(){if(live)return true;const view=getView(),visual=view?.schoolView?.robotView??view?.homeView;if(!visual)return false;const station=visual.station??view.station;return ui.workshop('꼬마 로봇 공방',BODY,()=>{const saved=validateRobotSave(getProgress().homeRobot)??initialRobotSave(),root=$('robot-panel'),s={alive:true,saved,state:initialRobot(saved.selected,saved.programs[saved.selected]??[]),target:[],history:[],listeners:[],visual,delay:.48};live=s;s.outcome=mountActivityOutcome($('robot-complete'),{onRetry:()=>{apply(s,{type:'REWIND'});$('robot-run').focus();},onExit:()=>ui.close()});const actors=getActors();$('robot-computer').hidden=!actors?.scene;s.viewport=createViewport({worldScene:actors?.scene,zoneRoot:view.root,station,canvas:$('robot-world-canvas'),fallback:$('robot-map-fallback'),reduced,onFallback(){if(live===s)$('robot-render-note').hidden=false;}});if(actors?.player&&actors?.model&&actors?.poser)s.session=createSession({...actors,zoneRoot:view.root,station,reduced});
  bind(s,root,'click',e=>{const b=e.target?.closest?.('[data-robot-action]');if(!b||!root.contains(b)||b.disabled||live!==s)return;const a=b.dataset.robotAction,path=parsePath(b.dataset.path);if(a==='save'){save(s);render(s);return;}if(a==='computer'){const showing=s.viewport.computer?.();$('robot-computer').setAttribute('aria-pressed',String(!!showing));$('robot-computer').textContent=showing?'로봇 보기':'도름이 보기';return;}if(a==='rotate'){s.viewport.rotate();return;}if(a==='top'){$('robot-top').setAttribute('aria-pressed',String(s.viewport.top()));return;}if(a==='run'){apply(s,{type:'START'});return;}if(a==='pause'){apply(s,{type:'PAUSE'});return;}if(a==='rewind'){apply(s,{type:'REWIND'});return;}if(a==='step'){apply(s,{type:'STEP'});return;}if(a==='stage'){chooseStage(s,b.dataset.id);return;}if(a==='next'){chooseStage(s,STAGES[STAGES.indexOf(stageById(s.state.stageId))+1]?.id);return;}if(s.state.phase==='running')return;if(a==='target'){s.target=path;render(s,{editor:true});return;}if(a==='clear'){s.target=[];edit(s,[]);return;}if(a==='undo'){const p=s.history.pop();if(!p)return;s.target=[];s.state=reduceRobot(s.state,{type:'EDIT',program:p});save(s);render(s,{editor:true});return;}if(a==='append'){const type=b.dataset.command,stage=stageById(s.state.stageId);if(!stage.palette.includes(type))return;const node=type==='repeat'?{type,count:3,body:[]}:type==='if'?{type,sensor:stage.sensors[0],body:[]}:{type};const p=editProgram(s.state.program,{type:'append',path:s.target,node});if(p&&node.body){let body=p;for(const i of s.target)body=body[i].body;s.target=[...s.target,body.length-1];}edit(s,p);return;}if(['remove','up','down'].includes(a)){s.target=[];edit(s,editProgram(s.state.program,{type:a==='remove'?'remove':'move',path,delta:a==='up'?-1:1}));}});
  bind(s,root,'change',e=>{if(live!==s)return;const b=e.target,type=b.dataset.robotChange;if(type==='speed'){s.delay=b.value==='.85'?.85:.48;return;}if(s.state.phase==='running')return;if(type==='count'||type==='sensor'){const path=parsePath(b.dataset.path),patch=type==='count'?{count:Number(b.value)}:{sensor:b.value};if(type==='sensor'&&!stageById(s.state.stageId).sensors.includes(b.value))return;edit(s,editProgram(s.state.program,{type:'update',path,patch}));}});
  const pause=()=>{if(live===s)apply(s,{type:'PAUSE'});};bind(s,win,'blur',pause);bind(s,doc,'visibilitychange',()=>{if(doc.hidden)pause();});stageHeader(s);render(s,{editor:true});$('robot-save-status').textContent='명령은 자동 저장 · 닫았다 돌아오면 처음 위치부터 시작해요';return ()=>{if(live===s)close();};
 },{kind:'robot-workshop',closeLabel:'나가기'});}
 return {open,close,get active(){return !!live;},tick(dt){const s=live;if(!s||doc.hidden)return;apply(s,{type:'TICK',dt,token:s.state.generation,delay:s.delay});s.viewport.tick(dt);s.visual?.tickLab?.(dt);s.session?.update(s.state.steps,s.state.phase==='running');},snapshot(){return live?structuredClone(live.state):null;}};
}
